// Разбираем payload бота и готовим вложения как бинарные свойства.
// Бот шлёт: { to, subject, text, from, meta, attachments:[{filename, mime_type, content_base64}] }
const b = ($json.body !== undefined) ? $json.body : $json;

// (необязательно) проверка общего секрета: включите WEBHOOK_TOKEN в .env бота
// и переменную EXPECTED_TOKEN в n8n, затем раскомментируйте:
// const token = ($node["Webhook"].json.headers || {})["x-webhook-token"];
// if ($env.EXPECTED_TOKEN && token !== $env.EXPECTED_TOKEN) {
//   throw new Error("Неверный X-Webhook-Token");
// }

const atts = Array.isArray(b.attachments) ? b.attachments : [];
const binary = {};
atts.forEach((a, i) => {
  binary['attachment_' + i] = {
    data: a.content_base64,
    mimeType: a.mime_type || 'application/pdf',
    fileName: a.filename || ('document_' + i + '.pdf'),
  };
});

return [{
  json: {
    to: b.to,
    from: b.from,
    subject: b.subject || 'Уведомление',
    text: b.text || '',
    meta: b.meta || {},
    // Список бинарных свойств для узла отправки (через запятую)
    attachmentProps: Object.keys(binary).join(','),
  },
  binary,
}];
